// These observations describe a conflict between a literal source reading and the current chart.
// An observation does not supply a rule condition.
const disputedZiweiSources = new Set([
  'ziwei-v2-fuqigong-p101022-002',
  'ziwei-v2-fuqigong-p101022-003',
  'ziwei-v2-guanlugong-p101002-003',
  'ziwei-v2-c005-p101023-003',
]);

export function sourcePrerequisiteReview(claim) {
  if (disputedZiweiSources.has(claim.id)) return claimReviewNotes[claim.id];
  const match = claim.conditions.match;
  if (claim.source.book === '盲派命理经典' && claim.source.chapter === '盲派宫星定位断命法'
    && match?.status === 'needs_calculation' && match.requirements?.some(text => text.includes('宫合'))
    && claim.interpretation.limitations.some(text => text.includes('宫合'))) {
    return '提供资料明确声明宫星断语受宫合前提约束，机器条件也要求回查宫合及透藏口径。该前提尚未形成可执行条件；仅识别年、月、日、时的某个十神不足以启用整条断语。原文、缺口与 ID 保留，待独立核定后再接入。';
  }
  return null;
}

